public static Set getRebatePaymentTypes(ModuleInventCustVend _module, TAMRebateType _rebateType)
{
    Set enumSet = next getRebatePaymentTypes(_module, _rebateType);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) && _module == ModuleInventCustVend::Cust && _rebateType == TAMRebateType::Rebate)
    {
        enumSet.add(TAMRebatePaymentType::Fund);
    }

    return enumSet;
}

public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (!FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        return ret;
    }

    if (this.RebatePaymentType == TAMRebatePaymentType::Fund)
    {
        if (this.RebatePostingType != TAMRebatePostingAccountType::CustVend)
        {
            ret = checkFailed("@GlobalUnifiedPricing:RebateAccountTypeMustBeCustVendWithFundPayment");
        }

        if (!this.FundLedgerDimension)
        {
            ret = checkFailed(strFmt("@SYS26332", fieldId2PName(tableNum(TAMRebatePosting), fieldNum(TAMRebatePosting, FundLedgerDimension))));
        }

        if (!this.LedgerJournalNameIdFund)
        {
            ret = checkFailed(strFmt("@SYS26332", fieldId2PName(tableNum(TAMRebatePosting), fieldNum(TAMRebatePosting, LedgerJournalNameIdFund))));
        }
    }

    if (this.FundLedgerDimension && !this.RebateLedgerDimension)
    {
        ret = checkFailed(strFmt("@SYS26332", fieldId2PName(tableNum(TAMRebatePosting), fieldNum(TAMRebatePosting, RebateLedgerDimension))));
    }

    return ret;
}
